function makeRival(id,p){let c=company(id,true);Object.assign(c,{name:p.name,tier:p.tier,style:p.style,initialCash:p.cash,cash:p.cash,bornTick:p.bornTick||0,activationTick:p.activationTick||0,expandedLogistics:false});c.nodes=[];c.edges=[];let city=p.city||'hanbit';if(city!=='hanbit')c.cities.push(city);let kinds=p.product==='service'?DIGITAL:p.product==='packaging'?['mine','factory','factory','warehouse','store']:['mine','factory','warehouse','store'];if(p.product==='service')c.research.unlocked=['process','cloud'];if(p.product==='packaging')c.research.unlocked=['process','packaging'];kinds.forEach((kind,i)=>{let product=p.product==='packaging'&&i<2?'paper':DIGITAL.includes(kind)?digitalProduct(kind):p.product;c.nodes.push(makeNode(id+'n'+i,kind,product,130+i*230,170,city));});for(let i=0;i<c.nodes.length-1;i++)c.edges.push({id:id+'e'+i,from:c.nodes[i].id,to:c.nodes[i+1].id,cap:i===1?1:2,flow:0,blocked:0,flight:0,remaining:0});return c;}
export function validate(s){if(!s||s.gameId!==GAME_ID||s.schemaVersion!==13)throw Error('다른 게임 또는 지원하지 않는 저장 버전');if(!Number.isSafeInteger(s.tick)||s.tick<0||s.tick>1e9||!Number.isSafeInteger(s.nextId))throw Error('시간/ID 오류');for(let c of companies(s)){if(!c||!Number.isSafeInteger(c.cash)||c.cash<0||c.cash>1e14||!Array.isArray(c.nodes)||c.nodes.length>40||!Array.isArray(c.edges)||c.edges.length>100)throw Error('회사 데이터 오류');let ids=new Set();for(let n of c.nodes){if(!KINDS[n.kind]||!(SENSOR.includes(n.kind)?n.product===sensorProduct(n.kind):DIGITAL.includes(n.kind)?n.product===digitalProduct(n.kind):E_RECIPES[n.kind]?n.product===E_RECIPES[n.kind].output:FOOD_RECIPES[n.kind]?n.product===FOOD_RECIPES[n.kind].output:PHYSICAL.includes(n.product)||GOODS.includes(n.product))||ids.has(n.id)||!Number.isInteger(n.level)||n.level<1||n.level>5||!Number.isFinite(n.x)||!Number.isFinite(n.y)||Math.abs(n.x)>4000||Math.abs(n.y)>4000)throw Error('노드 오류');ids.add(n.id);if(!CITIES[n.city]||!c.cities?.includes(n.city))throw Error('노드 도시 오류');if(!SENSOR.includes(n.kind)&&!DIGITAL.includes(n.kind)&&!['lab','ad'].includes(n.kind)&&!PHYSICAL.includes(n.product))throw Error('제조 설비 상품 오류');if(SENSOR.includes(n.kind)&&Object.entries(n.stock).some(([p,q])=>q>0&&!(n.kind==='supplier'?['component']:n.kind==='assembler'?['component','sensor']:['sensor']).includes(p)))throw Error('센서 재고 오류');if(!SENSOR.includes(n.kind)&&(n.stock.component||n.stock.sensor))throw Error('비센서 재고 오류');if(DIGITAL.includes(n.kind)&&Object.entries(n.stock).some(([p,q])=>q>0&&!(n.kind==='collector'?['data']:n.kind==='datacenter'?['data','service']:['service']).includes(p)))throw Error('디지털 재고 오류');if(!DIGITAL.includes(n.kind)&&(n.stock.data||n.stock.service))throw Error('제조 재고 오류');if(n.kind==='ad'&&(![0,10,25,50,100].includes(n.budget)||!Number.isSafeInteger(n.spent)||n.spent<0||n.spent>100))throw Error('광고 예산 오류');for(let p of Object.keys(PRODUCTS))if(!Number.isSafeInteger(n.stock?.[p])||n.stock[p]<0||n.stock[p]>200)throw Error('재고 오류');}let previous=[];for(let e of c.edges){if(e.remaining!==undefined&&(!Number.isInteger(e.remaining)||e.remaining<0||e.remaining>3))throw Error('운송 지연 오류');if(!Number.isInteger(e.cap)||e.cap<1||e.cap>8||!Number.isInteger(e.flight)||e.flight<0||e.flight>8)throw Error('운송 오류');let temp={...c,edges:previous};if(canConnect(temp,e.from,e.to))throw Error('잘못된 연결');previous.push(e);}for(let p of GOODS)if(!Number.isSafeInteger(c.price[p])||c.price[p]<priceBounds(p)[0]||c.price[p]>priceBounds(p)[1])throw Error('가격 오류');}for(let c of companies(s)){let r=c.research;if(!r||!Array.isArray(r.unlocked)||r.unlocked.length>Object.keys(TECHS).length||new Set(r.unlocked).size!==r.unlocked.length||r.unlocked.some(id=>!TECHS[id]||TECHS[id].prereq.some(p=>!r.unlocked.includes(p))))throw Error('기술 해금 오류');if(r.active&&(!TECHS[r.active.id]||r.unlocked.includes(r.active.id)||TECHS[r.active.id].prereq.some(p=>!r.unlocked.includes(p))||!Number.isInteger(r.active.progress)||r.active.progress<0||r.active.progress>=TECHS[r.active.id].points||r.active.paid!==TECHS[r.active.id].cost&&r.active.paid!==({process:4500,logistics:5500}[r.active.id]||TECHS[r.active.id].cost)))throw Error('연구 진행 오류');if(!r.unlocked.includes('precision')&&c.nodes.some(n=>SENSOR.includes(n.kind)))throw Error('잠긴 센서 설비');if(!r.unlocked.includes('cloud')&&c.nodes.some(n=>DIGITAL.includes(n.kind)||n.product==='service'))throw Error('잠긴 디지털 설비');if(!r.unlocked.includes('packaging')&&c.nodes.some(n=>n.product==='packaging'&&!['mine','lab'].includes(n.kind)))throw Error('잠긴 상품 설비');}
for(let c of companies(s)){if(!Array.isArray(c.cities)||new Set(c.cities).size!==c.cities.length||!c.cities.includes('hanbit')||c.cities.some(id=>!CITIES[id]))throw Error('도시 해금 오류');let b=c.regional?.cheolwon,m=s.regional?.cheolwon;for(let p of GOODS)if(!Number.isSafeInteger(b?.price?.[p])||b.price[p]<priceBounds(p)[0]||b.price[p]>priceBounds(p)[1]||!Number.isInteger(b?.brand?.[p])||b.brand[p]<0||b.brand[p]>10000||!Number.isSafeInteger(b?.sales?.[p])||b.sales[p]<0||!Number.isSafeInteger(b?.daily?.[p])||b.daily[p]<0||!Number.isSafeInteger(m?.market?.[p])||m.market[p]<1||m.market[p]>10000||!([...V_GOODS,...H_GOODS].includes(p)?Number.isFinite(m?.demand?.[p]):Number.isSafeInteger(m?.demand?.[p]))||m.demand[p]<0||m.demand[p]>100)throw Error('도시 시장 오류');}if(!Array.isArray(s.competitors)||s.competitors.length<7||s.competitors.length>11||!s.ecosystem||!Number.isInteger(s.ecosystem.nextEntryTick)||!Number.isInteger(s.ecosystem.entryCount))throw Error('경쟁 생태계 오류');let companyIds=new Set();for(let c of companies(s)){if(companyIds.has(c.id))throw Error('회사 중복');companyIds.add(c.id);if(!Number.isSafeInteger(c.initialCash)||c.initialCash<0||!Number.isSafeInteger(c.earnedProfit)||!Number.isInteger(c.activationTick)||c.activationTick<0||!Number.isInteger(c.bornTick)||!Number.isInteger(c.distress)||c.distress<0||!TIERS[c.tier]||!STYLES[c.style]||!['active','bankrupt','acquired'].includes(c.status)||typeof c.name!=='string'||c.name.length>80)throw Error('회사 상태 오류');}if(!Number.isFinite(s.lastSettledAt)||s.lastSettledAt<0||s.lastSettledAt>8640000000000000||!Number.isSafeInteger(s.lifetimeProfit))throw Error('시각/이익 오류');for(let c of companies(s)){for(let key of ['revenue','raw','production','transport','fixed','marketing','power','research','capital'])if(!Number.isSafeInteger(c.ledger?.[key])||Math.abs(c.ledger[key])>1e14)throw Error('원장 오류');for(let key of ['revenue','raw','production','transport','fixed','marketing','power','profit'])if(!Number.isSafeInteger(c.last?.[key]))throw Error('손익 오류');for(let p of GOODS)if(!Number.isInteger(c.brand?.[p])||c.brand[p]<0||c.brand[p]>10000||!Number.isSafeInteger(c.sales?.[p])||c.sales[p]<0||!Number.isSafeInteger(c.daily?.[p])||c.daily[p]<0||!Number.isSafeInteger(s.market?.[p])||s.market[p]<1||s.market[p]>10000||!([...V_GOODS,...H_GOODS].includes(p)?Number.isFinite(s.demand?.[p]):Number.isSafeInteger(s.demand?.[p]))||s.demand[p]<0||s.demand[p]>100)throw Error('시장 오류');for(let n of c.nodes)if(Object.values(n.stock).reduce((a,b)=>a+b,0)>limit(n))throw Error('창고 초과');}if(!Array.isArray(s.logs)||s.logs.length>35||s.logs.some(l=>typeof l.text!=='string'||l.text.length>1000||!Number.isSafeInteger(l.tick))||!Array.isArray(s.history)||s.history.length>28||s.history.some(h=>!['day','profit','cash','share'].every(k=>Number.isSafeInteger(h[k])))||!Array.isArray(s.milestones)||s.milestones.some(v=>typeof v!=='string'))throw Error('기록 오류');validateFinance(s);validateStrategy(s);validateCycle(s,{CITIES,GOODS});validateTakeovers(s);validateDefense(s);validateOffline(s);validateDemand(s);validateElectronics(s,eAPI);validateAssembly(s,eAPI);validateFood(s);validateFoodBranches(s,eAPI);validateVehicles(s,eAPI);validateAppliances(s,eAPI);validateMeat(s,eAPI);validateClothing(s,eAPI);validatePlanning(s);validateObservatory(s);validateB2(s,b2API);validatePace(s);return true;}

export function startResearch(s,id,company=s.player){let t=TECHS[id],c=company;if(C_TECH_IDS.includes(id)&&s.tick<7200)return'의류 연구는7200틱(120분)부터입니다';if(!t)return'알 수 없는 기술';if(M_TECH_IDS.includes(id)&&s.tick<7200)return'축산식품 연구는7200틱(120분)부터입니다';if(H_TECH_IDS.includes(id)&&s.tick<7200)return'가전 연구는7200틱(120분)부터입니다';if(V_TECH_IDS.includes(id)&&s.tick<7200)return'차량 연구는7200틱(120분)부터입니다';if(F_NEW_TECHS.includes(id)&&s.tick<5400)return'식품분기 연구는5400틱(90분)부터입니다';if(A_TECHS.includes(id)&&s.tick<5400)return'조립 연구는5400틱(90분)부터입니다';if(E_TECHS[id]&&s.tick<2700)return'전자부품 연구는2700틱(45분)부터입니다';if(FOOD_TECHS[id]&&s.tick<900)return'농업 연구는900틱(15분)부터입니다';if(id==='precision'&&s.tick<2400)return'정밀 센서 공정은2400틱(40분)부터입니다';if(['cloud','packaging','precision'].includes(id)){let error=paceError(s,c,id);if(error)return error;}if(c.research.unlocked.includes(id))return'이미 완료한 연구';if(c.research.active)return'다른 연구가 진행 중입니다';if(t.prereq.some(k=>!c.research.unlocked.includes(k)))return'선행 연구가 필요합니다';if(!c.nodes.some(n=>n.kind==='lab'))return'연구소를 먼저 건설하세요';if(c.cash<t.cost+5000)return'연구비 외에 5,000 C 예비 현금이 필요합니다';if(!spend(c,'research',t.cost))return'현금이 부족합니다';c.research.active={id,progress:0,paid:t.cost};log(s,(c===s.player?'내 회사':c.name)+' 연구 시작 · '+t.name);return null;}
function advanceResearch(s,c){let a=c.research.active;if(!a||c.stopped||c.cash<5000)return;let labs=c.nodes.filter(n=>n.kind==='lab');if(!labs.length)return;a.progress+=Math.min(3,labs.reduce((t,n)=>t+n.level,0));if(a.progress>=TECHS[a.id].points){c.research.unlocked.push(a.id);log(s,(c===s.player?'내 회사':c.name)+' 연구 완료 · '+TECHS[a.id].name);c.research.active=null;}}
export function brandMultiplier(c,p,city='hanbit'){return 1+cityBook(c,city).brand[p]/7000;}
export function migrate(input){let hadAssembly=input?.schemaVersion===13&&input?.assembly?.version===1;let hadFood=input?.schemaVersion===13&&input?.foodVersion===1;let s=JSON.parse(JSON.stringify(input));if(s?.gameId===GAME_ID&&s.schemaVersion===1){for(let c of [s.player,s.ai]){c.brand={paper:0,furniture:0};c.ledger.marketing=0;c.last.marketing=0;}s.schemaVersion=2;}if(s?.gameId===GAME_ID&&s.schemaVersion===2){for(let c of [s.player,s.ai]){c.research={unlocked:[],active:null};c.ledger.research=0;for(let n of c.nodes)n.stock.packaging=0;c.price.packaging=350;c.brand.packaging=0;c.sales.packaging=0;c.daily.packaging=0;}s.market.packaging=350;s.demand.packaging=2;s.schemaVersion=3;}if(s?.gameId===GAME_ID&&s.schemaVersion===3){for(let c of [s.player,s.ai]){c.ledger.power=0;c.last.power=0;c.price.service=420;c.brand.service=0;c.sales.service=0;c.daily.service=0;for(let n of c.nodes){n.stock.data=0;n.stock.service=0;}}s.market.service=420;s.demand.service=2;s.schemaVersion=4;}if(s?.gameId===GAME_ID&&s.schemaVersion===4){for(let c of [s.player,s.ai]){c.cities=['hanbit'];c.regional={cheolwon:{price:{paper:120,furniture:285,packaging:350,service:420,sensor:260},brand:{paper:0,furniture:0,packaging:0,service:0,sensor:0},sales:{paper:0,furniture:0,packaging:0,service:0,sensor:0},daily:{paper:0,furniture:0,packaging:0,service:0,sensor:0}}};for(let n of c.nodes)n.city='hanbit';for(let e of c.edges)e.remaining=e.flight?1:0;}s.regional={cheolwon:{market:{paper:120,furniture:285,packaging:350,service:420,sensor:260},demand:{...CITIES.cheolwon.demand}}};s.schemaVersion=5;}if(s?.gameId===GAME_ID&&s.schemaVersion===5){for(let c of [s.player,s.ai])Object.assign(c,{initialCash:c===s.player?32000:35000,name:c===s.player?'내 회사':'바닥상사',tier:c===s.player?'minor':'major',style:c===s.player?'local':'dump',status:'active',activationTick:0,distress:0,earnedProfit:0,bornTick:0});s.competitors=seedRivals();for(let c of s.competitors)c.activationTick=Math.max(s.tick+600,c.activationTick);s.ecosystem={nextEntryTick:s.tick+3600,entryCount:0};s.schemaVersion=6;}if(s?.gameId===GAME_ID&&s.schemaVersion===6){addFinance(s);s.schemaVersion=7;}if(s?.gameId===GAME_ID&&s.schemaVersion===7){addTakeovers(s);s.schemaVersion=8;}if(s?.gameId===GAME_ID&&s.schemaVersion===8){addDefense(s);s.schemaVersion=9;}if(s?.gameId===GAME_ID&&s.schemaVersion===9){s.offline={limitSeconds:28800,safetyCash:5000,lastReport:null};s.schemaVersion=10;}if(s?.gameId===GAME_ID&&s.schemaVersion===10){s.demandCredits={};s.marketWindows={};s.schemaVersion=11;}if(s?.gameId===GAME_ID&&s.schemaVersion===11){initPace(s,true);s.schemaVersion=12;}if(s?.gameId===GAME_ID&&s.schemaVersion===12){for(let c of companies(s)){for(let n of c.nodes){n.stock.component=0;n.stock.sensor=0;}for(let city of Object.keys(CITIES)){let b=cityBook(c,city);b.price.sensor=260;b.brand.sensor=0;b.sales.sensor=0;b.daily.sensor=0;}}for(let city of Object.keys(CITIES)){let m=cityMarket(s,city);m.market.sensor=260;m.demand.sensor=1;}for(let city of Object.keys(CITIES))s.pace.sales[city].sensor=0;s.schemaVersion=13;}if(s?.gameId===GAME_ID&&s.schemaVersion===13&&!hadFood)initFood(s);if(s?.gameId===GAME_ID&&s.schemaVersion===13&&!s.b2b)initB2(s);if(s?.gameId===GAME_ID&&s.schemaVersion===13&&!s.electronicsVersion)initElectronics(s,eAPI);if(s.electronicsVersion===1&&s.industry)s.industry.budgets??={};if(s?.gameId===GAME_ID&&s.schemaVersion===13&&!hadAssembly)initAssembly(s,eAPI);if(s?.gameId===GAME_ID&&s.schemaVersion===13&&!s.foodBranches)initFoodBranches(s,eAPI);if(s?.gameId===GAME_ID&&s.schemaVersion===13&&!s.vehicles)initVehicles(s,eAPI);if(s?.gameId===GAME_ID&&s.schemaVersion===13&&!s.appliances)initAppliances(s,eAPI);if(s?.gameId===GAME_ID&&s.schemaVersion===13&&!s.meat)initMeat(s,eAPI);if(s?.gameId===GAME_ID&&s.schemaVersion===13&&!s.clothing)initClothing(s,eAPI);if(s?.gameId===GAME_ID&&s.schemaVersion===13){initPlanning(s);initStrategy(s);initCycle(s,true);}validate(s);return s;}

function shareGroupTech(s){for(let root of companies(s).filter(c=>!c.controller)){let group=groupCompanies(s,root);if(group.length<2)continue;let tech=[...new Set(group.flatMap(c=>c.research.unlocked))];for(let c of group){let allowed=[...tech].filter(id=>(!C_TECH_IDS.includes(id)||s.tick>=7200)&&(!M_TECH_IDS.includes(id)||s.tick>=7200)&&(!H_TECH_IDS.includes(id)||s.tick>=7200)&&(!V_TECH_IDS.includes(id)||s.tick>=7200)&&(!F_NEW_TECHS.includes(id)||s.tick>=5400)&&(!A_TECHS.includes(id)||s.tick>=5400)&&(!E_TECHS[id]||s.tick>=2700)&&(!['packaging','cloud','precision'].includes(id)||!paceError(s,c,id)));c.research.unlocked=allowed;if(c.research.active&&allowed.includes(c.research.active.id))c.research.active=null;}}}

function validateOffline(s){let o=s.offline,r=o?.lastReport;if(!o||o.limitSeconds!==28800||![0,5000,10000,20000].includes(o.safetyCash))throw Error('오프라인 설정 오류');for(let c of companies(s))if(c.bankruptcyGraceUntil!==undefined&&(!Number.isSafeInteger(c.bankruptcyGraceUntil)||c.bankruptcyGraceUntil<0||c.bankruptcyGraceUntil>s.tick+300))throw Error('복귀 대응시각 오류');if(!r)return;if(r.cycle&&(!Array.isArray(r.cycle.counts)||r.cycle.counts.length!==4||r.cycle.counts.some(n=>!Number.isSafeInteger(n)||n<0)||r.cycle.counts.reduce((a,b)=>a+b,0)>r.seconds||!['준비','회복','호황','둔화','불황'].includes(r.cycle.current)||r.cycle.startTick!==s.cycle.startTick))throw Error('복귀 경기 요약 오류');if(r.shareBasis!==undefined&&r.shareBasis!==60)throw Error('정산평균 기준 오류');for(let k of ['from','to'])if(!Number.isFinite(r[k])||r[k]<0||r[k]>s.lastSettledAt)throw Error('정산시각 오류');for(let k of ['elapsed','seconds','startTick','activeSeconds','safetySeconds','stockoutSeconds','shareBefore','shareAfter'])if(!Number.isSafeInteger(r[k])||r[k]<0)throw Error('정산숫자 오류');if(r.from>r.to||r.seconds>28800||r.seconds>r.elapsed||r.activeSeconds+r.safetySeconds>r.seconds||r.stockoutSeconds>r.seconds||r.shareBefore>100||r.shareAfter>100||r.startTick+r.seconds>s.tick||!Number.isSafeInteger(r.cashChange)||typeof r.capped!=='boolean'||typeof r.clockReversed!=='boolean')throw Error('정산범위 오류');for(let k of ['revenue','raw','production','transport','fixed','marketing','power','research','capital'])if(!Number.isSafeInteger(r.ledger?.[k]))throw Error('정산비용 오류');for(let k of ['research','risks','events'])if(!Array.isArray(r[k])||r[k].length>50||r[k].some(v=>typeof v!=='string'||v.length>500))throw Error('정산문구 오류');if(!Array.isArray(r.companies)||r.companies.length>13||r.companies.some(c=>typeof c.id!=='string'||typeof c.name!=='string'||c.name.length>80||![c.before,c.after].every(n=>Number.isSafeInteger(n)&&n>=0)))throw Error('정산회사 오류');}

export function salesWindow(s,c=s.player,city=null,product=null){let mine=0,total=0,ticks=0;for(let [key,window]of Object.entries(s.marketWindows)){let [id,p]=key.split(':');if(city&&id!==city||product&&p!==product)continue;ticks=Math.max(ticks,window.length);for(let row of window)for(let [owner,n]of Object.entries(row)){total+=n;if(owner===c.id)mine+=n;}}return{mine,total,ticks,share:total?100*mine/total:0};}
function validateDemand(s){let ids=new Set(companies(s).map(c=>c.id)),validKey=k=>{let bits=k.split(':');return bits.length===2&&!!CITIES[bits[0]]&&GOODS.includes(bits[1]);},obj=x=>x&&typeof x==='object'&&!Array.isArray(x);if(!obj(s.demandCredits)||!obj(s.marketWindows)||Object.keys(s.demandCredits).length>GOODS.length*2||Object.keys(s.marketWindows).length>GOODS.length*2)throw Error('수요 저장 오류');for(let [key,row]of Object.entries(s.demandCredits)){if(!validKey(key)||!obj(row)||Object.keys(row).length>13||Object.entries(row).some(([id,n])=>!ids.has(id)||!Number.isFinite(n)||Math.abs(n)>12))throw Error('수요 잔액 오류');}for(let [key,window]of Object.entries(s.marketWindows)){if(!validKey(key)||!Array.isArray(window)||window.length>60||window.length>s.tick)throw Error('시장평균 구간 오류');for(let row of window){if(!obj(row)||Object.keys(row).length>13||Object.entries(row).some(([id,n])=>!ids.has(id)||!Number.isSafeInteger(n)||n<0||n>100)||Object.values(row).reduce((a,n)=>a+n,0)>100)throw Error('시장평균 판매량 오류');}}}

function sensorAI(s){if(s.tick<2400||s.tick%60)return;for(let id of ['r2','r3']){let c=companies(s).find(c=>c.id===id);if(!c||!activeCompany(s,c)||c.controller||c.stopped)continue;let city=id==='r2'?'hanbit':'cheolwon';if(!c.cities.includes(city))continue;if(!c.nodes.some(n=>n.kind==='lab')&&c.cash>=60000&&c.nodes.length<40)build(s,'lab','paper',950,500,city,c);if(!c.research.active&&c.cash>=60000){let next=['process','logistics','precision'].find(k=>!c.research.unlocked.includes(k));if(next)startResearch(s,next,c);}if(c.research.unlocked.includes('precision')&&!c.nodes.some(n=>n.kind==='supplier')&&c.cash>=45000&&c.nodes.length<=37){let ns=SENSOR.map((k,i)=>build(s,k,'sensor',200+i*240,850,city,c));for(let i=0;i<2;i++)connect(s,ns[i].id,ns[i+1].id,c);}}}

function initFoodCompany(c){for(let n of c.nodes)for(let p of Object.keys(FOOD_PRODUCTS))n.stock[p]??=0;for(let id of Object.keys(CITIES)){let b=cityBook(c,id);for(let p of FOOD_GOODS){b.price[p]??=PRODUCTS[p].base;for(let key of ['brand','sales','daily'])b[key][p]??=0;}}}
function initFood(s){s.foodVersion=1;for(let c of companies(s))initFoodCompany(c);for(let id of Object.keys(CITIES)){let m=cityMarket(s,id);for(let p of FOOD_GOODS){m.market[p]??=PRODUCTS[p].base;m.demand[p]??=[...F_NEW_GOODS,...M_GOODS].includes(p)?0:2;}}initObservatory(s);}
function validateFood(s){if(s.foodVersion!==1)throw Error('식품 확장 버전 오류');for(let c of companies(s))for(let n of c.nodes){let r=FOOD_RECIPES[n.kind],tech=foodTech(n.product);if(tech&&!c.research.unlocked.includes(tech))throw Error('잠긴 식품 설비');if(r&&Object.entries(n.stock).some(([p,q])=>q>0&&p!==r.output&&!Object.hasOwn(r.inputs,p)))throw Error('식품 원료 오류');if(n.kind==='factory'&&FOOD_PRODUCTS[n.product])throw Error('식품 가공 설비 오류');if(['store','ad'].includes(n.kind)&&FOOD_PRODUCTS[n.product]&&!FOOD_GOODS.includes(n.product))throw Error('원물 소비시장 오류');}}
function foodAI(s){if(s.tick<900||s.tick%60)return;for(let id of ['r0','r3']){let c=companies(s).find(c=>c.id===id);if(!c||!activeCompany(s,c)||c.controller||c.stopped||c.cash<90000||c.nodes.length>36)continue;let tech=id==='r0'?'dairy':'baking',city=id==='r0'?'cheolwon':'hanbit';if(!c.cities.includes(city))continue;if(!c.nodes.some(n=>n.kind==='lab'))build(s,'lab','paper',900,500,city,c);if(!c.research.active){let next=['process','agriculture',tech].find(t=>!c.research.unlocked.includes(t));if(next)startResearch(s,next,c);}if(!c.research.unlocked.includes(tech)||c.nodes.some(n=>n.kind==='dairyfarm'||n.kind==='wheatfarm'))continue;let kinds=tech==='dairy'?['dairyfarm','dairyplant','warehouse','store']:['wheatfarm','mill','bakery','store'],p=tech==='dairy'?'yogurt':'bread',nodes=[];for(let k of kinds){let n=build(s,k,p,100+nodes.length*240,850,city,c);if(typeof n==='string')break;nodes.push(n);}for(let i=1;i<nodes.length;i++)connect(s,nodes[i-1].id,nodes[i].id,c);log(s,c.name+' 식품 산업 진출 · 자체 자본과 연구로 설비 건설');}}

export const b2API={capacity,limit,spend,rootCompany,eInputLimit};

export const eAPI={companies,CITIES,cityBook,cityMarket,cityOf,activeCompany,clamp};
